/**
 * @param {Array} arr
 * @param {number} depth
 * @return {Array}
 */
var flat = function (arr, n) {
    const out = [];

    // depth = nesting depth of the elements of `a` (top-level array has depth 0)
    const walk = (a, depth) => {
        for (const x of a) {
            if (Array.isArray(x) && depth < n) {
                walk(x, depth + 1);   // flatten this sub-array: its elements are one level deeper
            } else {
                out.push(x);          // number, or a sub-array we are not allowed to flatten
            }
        }
    };

    walk(arr, 0);
    return out;
};
